/**
 * @file src/components/PartnerStrip.jsx
 * Deretan logo: NuSaJoy dan mitra.
 *
 * Logo mitra (Jagoan Hosting, ngalup.co, Garuda Spark, Komdigi) sudah tertanam
 * di bagian bawah file ini (INLINE_LOGOS), jadi tidak perlu folder gambar.
 *
 * Logo NuSaJoy memakai komponen NuSaJoyLogo. Jika suatu hari ingin memakai
 * file gambar, simpan sebagai  src/assets/partners/nusajoy.(svg|png|webp)
 * dan file itu otomatis dipakai.
 *
 * Logo persegi/bulat dan logo lebar dibatasi tinggi yang sama lewat max-h
 * agar bobot visualnya seimbang.
 */

import { Component } from 'react';

import * as LogoModule from './NuSaJoyLogo.jsx';

/* Namespace import: aman walau NuSaJoyLogo diekspor sebagai default atau named. */
const NuSaJoyLogo = LogoModule.default ?? LogoModule.NuSaJoyLogo ?? null;

const LOGO_FILES = import.meta.glob(
  '../assets/partners/*.{svg,png,webp,jpg,jpeg}',
  { eager: true, query: '?url', import: 'default' },
);

const getLogoUrl = (slug) => {
  if (INLINE_LOGOS[slug]) {
    return INLINE_LOGOS[slug];
  }

  const match = Object.keys(LOGO_FILES).find(
    (path) =>
      path
        .split('/')
        .pop()
        .replace(/\.[^.]+$/, '')
        .toLowerCase() === slug,
  );

  return match ? LOGO_FILES[match] : null;
};

const PARTNERS = [
  { slug: 'nusajoy', name: 'NuSaJoy', isBrand: true },
  { slug: 'jagoan-hosting', name: 'Jagoan Hosting' },
  { slug: 'ngalup', name: 'ngalup.co' },
  { slug: 'garuda-spark', name: 'Garuda Spark' },
  { slug: 'komdigi', name: 'Komdigi' },
];

function NameFallback({ name }) {
  return (
    <span className="font-['Outfit'] text-[15px] font-semibold text-[#68736D]">
      {name}
    </span>
  );
}

/** Jika komponen logo gagal dirender, tampilkan nama saja. */
class LogoBoundary extends Component {
  constructor(props) {
    super(props);

    this.state = { failed: false };
  }

  static getDerivedStateFromError() {
    return { failed: true };
  }

  componentDidCatch(error) {
    console.error('NuSaJoy: NuSaJoyLogo gagal dirender.', error);
  }

  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

function PartnerLogo({ partner }) {
  const url = getLogoUrl(partner.slug);

  if (url) {
    return (
      <img
        src={url}
        alt={partner.name}
        loading="lazy"
        className="max-h-12 w-auto max-w-[150px] object-contain sm:max-h-14"
      />
    );
  }

  if (partner.isBrand && NuSaJoyLogo) {
    return (
      <LogoBoundary fallback={<NameFallback name={partner.name} />}>
        <NuSaJoyLogo />
      </LogoBoundary>
    );
  }

  return <NameFallback name={partner.name} />;
}

export default function PartnerStrip({ className = '' }) {
  return (
    <section
      aria-label="NuSaJoy dan mitra"
      className={`rounded-[22px] border border-[#DDE2D9] bg-[#FFFDF7] px-5 py-4 ${className}`}
    >
      <ul className="grid grid-cols-3 items-center justify-items-center gap-x-4 gap-y-4 sm:grid-cols-5">
        {PARTNERS.map((partner) => (
          <li key={partner.slug} className="flex h-14 items-center sm:h-16">
            <PartnerLogo partner={partner} />
          </li>
        ))}
      </ul>
    </section>
  );
}

/* ==========================================================================
   LOGO MITRA (WebP, latar transparan)
   ========================================================================== */

const INLINE_LOGOS = {
  'jagoan-hosting':
    'data:image/webp;base64,',
  'ngalup':
    'data:image/webp;base64,',
  'garuda-spark':
    'data:image/webp;base64,',
  'komdigi':
    'data:image/webp;base64,',
};
